"""Reproducible authored tasks. Expected facts are not generated by product helpers."""
from copy import deepcopy
import base64
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
VERTEX = "#version 300 es\nvoid main(){ vec2 p=vec2((gl_VertexID<<1)&2,gl_VertexID&2); gl_Position=vec4(p*2.0-1.0,0.0,1.0); }\n"
FRAGMENT = "#version 300 es\nprecision highp float;\nuniform vec2 u_resolution;\nuniform float u_time;\nout vec4 color;\nvoid main(){vec2 uv=gl_FragCoord.xy/u_resolution; color=vec4(uv,0.25,1.0);}\n"
COPY = "#version 300 es\nprecision highp float;\nuniform vec2 u_resolution;\nuniform sampler2D u_input;\nout vec4 color;\nvoid main(){vec2 uv=gl_FragCoord.xy/u_resolution; color=texture(u_input,uv);}\n"
PLASMA = """#version 300 es
precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform float u_intensity;
out vec4 color;
float hash21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float noise(vec2 p){
  vec2 i=floor(p),f=fract(p); f=f*f*(3.0-2.0*f);
  return mix(mix(hash21(i),hash21(i+vec2(1,0)),f.x),
             mix(hash21(i+vec2(0,1)),hash21(i+vec2(1,1)),f.x),f.y);
}
float fbm(vec2 p){
  float value=0.0,amplitude=0.5;
  mat2 rotation=mat2(0.8,-0.6,0.6,0.8);
  for(int i=0;i<5;i++){value+=amplitude*noise(p);p=rotation*p*2.03+vec2(4.3,1.7);amplitude*=0.5;}
  return value;
}
void main(){
  vec2 uv=gl_FragCoord.xy/u_resolution;
  vec2 p=(uv-0.5)*vec2(u_resolution.x/u_resolution.y,1.0)*3.0;
  float speed=0.25;
  float t=u_time*speed;
  vec2 warp=vec2(fbm(p+vec2(t,0)),fbm(p+vec2(4.1,-t)));
  float field=fbm(p+warp*3.0);
  float strands=pow(0.5+0.5*sin(field*24.0-t*2.0),5.0);
  vec3 coral=mix(vec3(0.025,0.045,0.12),vec3(1.0,0.32,0.22),field);
  coral+=strands*vec3(0.18,0.65,0.8)*u_intensity;
  coral*=1.0-0.35*dot(uv-0.5,uv-0.5);
  color=vec4(coral,1.0);
}
"""
REF_V = "$create.created_refs.vertex"
REF_F = "$create.created_refs.fragment"
REF_P = "$create.created_refs.pass"
VERSION = {"document_id": "$document_id", "expected_version": "$version"}


def check(path, value, op="equals"):
    return {"path": path, "value": value, "op": op}


def tool(identity, name, arguments=None, **kwargs):
    return {"id": identity, "tool": name, "arguments": arguments or {}, **kwargs}


def create(title="Aurora Study"):
    return tool("create", "shader_create", {"title": title, "expected_generation": 0})


def edit(identity, operations, objects=(), fields=(), **kwargs):
    return tool(identity, "shader_modify", {**VERSION, "operations": operations}, allowed_objects=list(objects), allowed_fields=list(fields), **kwargs)


def inspect(identity="inspect", section="summary", **kwargs):
    return tool(identity, "shader_inspect", {"document_id": "$document_id", "section": section, **kwargs})


def replace_source(identity="source", source=FRAGMENT):
    return edit(identity, [{"kind": "stage_replace", "stage_id": {"id": REF_F}, "source": source}], [REF_F])


def export():
    return tool("export", "shader_export", VERSION, unchanged=True)


def case(identity, category, prompt, steps, assertions, **kwargs):
    return {"case_id": identity, "category": category, "prompt": prompt, "steps": steps, "assertions": assertions, **kwargs}


def build_cases():
    cases = [case("simple-creation", "simple_creation", "Create an ESSL 3.00 Aurora Study with the default fullscreen pass and export its document. Do not claim it was compiled.", [create(), inspect(), export()], [check("summary.version", 1), check("document.stages", 2, "length"), check("document.passes", 1, "length")])]
    cases.append(case("incremental-source", "incremental_modification", "Replace only the fragment source with the requested UV gradient, then change its blue channel from 0.25 to 0.75. Preserve the vertex stage and pass IDs.", [create(), replace_source(), edit("patch", [{"kind": "stage_patch", "stage_id": {"id": REF_F}, "old_text": "uv,0.25", "new_text": "uv,0.75"}], [REF_F]), export()], [check("summary.version", 3), check("document.stages.1.source", FRAGMENT.replace("uv,0.25", "uv,0.75")), check("document.passes.0.id", REF_P)]))
    stages = [{"kind": "stage_create", "ref": "copy", "stage_kind": "fragment", "title": "Copy", "source": COPY}]
    passes = [{"kind": "pass_create", "ref": "post", "title": "Post", "vertex_stage_id": {"id": REF_V}, "fragment_stage_id": {"ref": "copy"}, "width": 64, "height": 64, "clear_color": [0, 0, 0, 1], "bindings": [{"name": "u_input", "source": {"kind": "pass", "pass_id": {"id": REF_P}}}]}]
    cases.append(case("multi-stage-pipeline", "multi_stage_creation", "Create a second fragment stage and an ordered post-processing pass that samples the existing pass. Export the editable pipeline; rendering is a separate action.", [create(), edit("pipeline", stages + passes, ["$pipeline.created_refs.copy", "$pipeline.created_refs.post"]), inspect("passes", "passes"), export()], [check("document.stages", 3, "length"), check("document.passes.1.bindings.0.source.pass_id", REF_P), check("summary.version", 2)]))
    cases.append(case("invalid-instruction-recovery", "recovery_from_invalid_instruction", "Attempt the requested self-dependent pass binding, report its rejection, then use a valid title correction without altering source.", [create(), edit("invalid", [{"kind": "binding_set", "pass_id": {"id": REF_P}, "name": "u_loop", "source": {"kind": "pass", "pass_id": {"id": REF_P}}}], succeeds=False), inspect(), edit("correction", [{"kind": "rename_document", "title": "Corrected"}], fields=["title"]), export()], [check("summary.version", 2), check("document.title", "Corrected"), check("document.passes.0.bindings", [])]))
    cases.append(case("inspect-before-edit", "inspect_before_edit", "Inspect stage metadata and the exact fragment source before editing only that returned stage.", [create(), inspect("stages", "stages"), inspect("source-read", "source", stage_id="$stages.items.1.id", version="$version"), edit("inspected-edit", [{"kind": "stage_replace", "stage_id": {"id": "$stages.items.1.id"}, "source": FRAGMENT}], ["$stages.items.1.id"]), export()], [check("document.stages.1.source", FRAGMENT), check("summary.version", 2)]))
    stale = edit("stale", [{"kind": "rename_document", "title": "Overwritten"}], succeeds=False)
    stale["arguments"]["expected_version"] = "$create.document.version"
    cases.append(case("stale-version", "stale_version", "Keep the accepted source edit. Reject a stale title update at v1 without replay, then inspect the current document.", [create(), replace_source(), stale, inspect(), export()], [check("summary.version", 2), check("document.title", "Aurora Study"), check("document.stages.1.source", FRAGMENT)]))
    cases.append(case("no-op-request", "no_op_request", "Set the title to its existing value. This must preserve version, content and generation.", [create(), edit("noop", [{"kind": "rename_document", "title": "Aurora Study"}], unchanged=True, checks=[check("studio_generation", 1), check("changed_ids", [])]), export()], [check("summary.version", 1), check("document.title", "Aurora Study")]))
    cases.append(case("ambiguous-request", "ambiguous_request", "Create a shader. Make it better, but do not invent a visual change: ask which parameter should change.", [create(), {"id": "ask", "kind": "answer", "text": "请明确要改的参数、数值和范围；当前源码尚未编译。"}, edit("clarified", [{"kind": "rename_document", "title": "Evening Aurora"}], fields=["title"]), export()], [check("summary.version", 2), check("document.title", "Evening Aurora")], clarification="Only rename the document to Evening Aurora; preserve all source and pass configuration."))
    large_source = VERTEX + "".join(f"// bounded shader module line {i:03d}: preserve exact content\n" for i in range(120))
    large_ops = [{"kind": "stage_create", "ref": f"module_{i}", "stage_kind": "vertex", "title": f"Module {i}", "source": large_source} for i in range(60)]
    large_steps = [create()]
    for offset in range(0, 60, 3):
        label = f"large-{offset}"
        large_steps.append(edit(label, large_ops[offset:offset+3], [f"${label}.created_refs.module_{i}" for i in range(offset, offset+3)]))
    large_steps.extend([inspect("page1", "stages", version="$version", limit=50), inspect("page2", "stages", version="$version", offset="$page1.next_offset", limit=50), inspect("page3", "stages", version="$version", offset="$page2.next_offset", limit=50), inspect("lines", "source", stage_id="$large-0.created_refs.module_0", version="$version", limit=50), export()])
    cases.append(case("large-document", "large_document", "Incrementally create 60 additional named shader modules with 120 comment lines each using bounded three-module batches. Inspect returned page cursors at one immutable version. Preserve the active pipeline.", large_steps, [check("document.stages", 62, "length"), check("document.stages.2.source", large_source), check("document.passes", 1, "length")]))
    uniforms = [{"kind": "uniform_create", "ref": f"gain_{i}", "pass_id": {"id": REF_P}, "name": f"u_gain_{i}", "type": "float", "value": i / 128} for i in range(128)]
    bounded_steps = [create()]
    for offset in (0, 64):
        label = f"uniforms-{offset}"
        bounded_steps.append(edit(label, uniforms[offset:offset+64], [f"${label}.created_refs.gain_{i}" for i in range(offset, offset+64)]))
    bounded_steps.extend([inspect("uniform-page", "uniforms", version="$version", limit=50), inspect(), export()])
    cases.append(case("bounded-context", "bounded_context", "Create 128 distinct float uniforms in two atomic batches. Inspect a bounded page and summary without placing the full uniform list or source in context.", bounded_steps, [check("document.uniforms", 128, "length"), check("summary.version", 3)]))
    human = {"id": "human", "kind": "human", "arguments": {**VERSION, "operations": [{"kind": "rename_document", "title": "Human preserved"}]}, "allowed_fields": ["title"]}
    cases.append(case("human-then-agent", "user_edit_followed_by_agent_edit", "After a human title edit, inspect the current head and replace only fragment source. Preserve the human title.", [create(), human, inspect(), replace_source(), export()], [check("summary.version", 3), check("document.title", "Human preserved"), check("document.stages.1.source", FRAGMENT)]))
    cases.append(case("negative-read-only", "negative_task", "Create a document and inspect it. Decline the request to execute an arbitrary external URL and make no further modifications.", [create(), inspect(), {"id": "decline", "kind": "answer", "text": "External URL execution is outside Shader operations. The saved document is unchanged and not compiled."}], [check("summary.version", 1), check("document.title", "Aurora Study")]))
    cases.append(case("gpu-unavailable", "unavailable_executor", "Create a shader, explicitly compile it, then request a preview with no active renderer. Report that neither action can succeed and preserve the document.", [create(), tool("compile", "compile", VERSION, succeeds=False), tool("preview", "render_preview", VERSION, succeeds=False), {"id": "unavailable", "kind": "answer", "text": "Both GPU actions failed because no visible active executor exists. No compile or preview result was produced."}], [check("summary.version", 1), check("document.title", "Aurora Study")]))
    rgba = bytes([255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 255, 255])
    texture_op = {"kind": "texture_create", "ref": "palette", "title": "Four corners", "width": 2, "height": 2, "rgba_base64": base64.b64encode(rgba).decode()}
    cases.append(case("texture-binding", "texture_binding", "Store a 2x2 top-left RGBA texture and bind it to the existing pass by returned identity. Preserve all shader source.", [create(), edit("texture", [texture_op], ["$texture.created_refs.palette"]), tool("bind", "texture_bind", {**VERSION, "pass_id": REF_P, "name": "u_palette", "source": {"kind": "texture", "texture_id": "$texture.created_refs.palette"}}, allowed_objects=[REF_P]), export()], [check("document.textures", 1, "length"), check("document.passes.0.bindings.0.source.texture_id", "$texture.created_refs.palette"), check("summary.version", 3)]))
    stress = [create("Coral Plasma"), replace_source(source=PLASMA), edit("add", [texture_op, {"kind": "uniform_create", "ref": "intensity", "pass_id": {"id": REF_P}, "name": "u_intensity", "type": "float", "value": 0.4}, {"kind": "stage_create", "ref": "scratch", "stage_kind": "fragment", "title": "Scratch", "source": FRAGMENT}], ["$add.created_refs.palette", "$add.created_refs.intensity", "$add.created_refs.scratch"]), edit("delete-scratch", [{"kind": "stage_remove", "stage_id": {"id": "$add.created_refs.scratch"}}], ["$add.created_refs.scratch"]), edit("local", [{"kind": "stage_patch", "stage_id": {"id": REF_F}, "old_text": "speed=0.25", "new_text": "speed=0.55"}], [REF_F]), edit("restructure", stages + passes, ["$restructure.created_refs.copy", "$restructure.created_refs.post"]), tool("parameter", "uniform_set", {**VERSION, "uniform_id": "$add.created_refs.intensity", "value": 0.7}, allowed_objects=["$add.created_refs.intensity"]), {"id": "ask", "kind": "answer", "text": "请明确更柔和是颜色、强度还是分辨率；尚未获得 GPU 编译结果。"}, edit("clarified", [{"kind": "pass_update", "pass_id": {"id": "$restructure.created_refs.post"}, "title": "Soft Post"}], ["$restructure.created_refs.post"]), human, deepcopy(stale), inspect("after-human"), tool("bind", "texture_bind", {**VERSION, "pass_id": REF_P, "name": "u_palette", "source": {"kind": "texture", "texture_id": "$add.created_refs.palette"}}, allowed_objects=[REF_P]), tool("undo-binding", "shader_undo", {**VERSION, "target_version": "$after-human.document.version"}, allowed_objects=[REF_P]), edit("refinement", [{"kind": "preview_set", "pass_id": {"id": "$restructure.created_refs.post"}, "width": 128, "height": 96, "time_seconds": 2.5}, {"kind": "rename_document", "title": "Coral Plasma · final"}], fields=["preview", "title"]), export()]
    cases.append(case("coral-plasma-stress", "creative_stress", "Create an editable five-octave domain-warped coral plasma, add texture and intensity control, remove scratch material, alter the local color, build a post pass, change the parameter, clarify ambiguity, preserve a human edit, reject a stale edit, undo one binding and refine the final preview configuration. Every Agent edit must use Shader tools; source persistence alone is not rendering proof.", stress, [check("document.title", "Coral Plasma · final"), check("document.stages", 3, "length"), check("document.passes", 2, "length"), check("document.uniforms.0.value", 0.7), check("document.passes.0.bindings", []), check("document.preview.width", 128), check("document.preview.height", 96), check("document.preview.time_seconds", 2.5)], stress=True, clarification="Only rename the post pass to Soft Post. Preserve all sources, then apply the separately listed exact changes."))
    return {"schema_version": "1.0", "cases": cases}


if __name__ == "__main__":
    (HERE / "cases.json").write_text(json.dumps(build_cases(), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
